import { SesInlineImage } from 'src/app/shared/mail/ses.service';

// ======================================= >> Code Starts Here << ========================== //


function inlineImage(cid: string, filename: string, base64: string): SesInlineImage {
    return { cid, filename, mimetype: 'image/png', content: Buffer.from(base64, 'base64') };
}

export const MAIL_LOGO = inlineImage('nextask-logo', 'nextask-logo.png', '');

export const MAIL_ICON_EMAIL = inlineImage('icon-email', 'icon-email.png', '');

export const MAIL_ICON_TIMER = inlineImage('icon-timer', 'icon-timer.png', '');

/** Hero art for the organization invitation email (the OTP email deliberately has none). */
export const MAIL_ILLUSTRATION: SesInlineImage | null = inlineImage('otp-illustration', 'otp-illustration.png', '');

/** Envelope illustration with a blank card, for the organization invitation email's dynamic logo badge. */
export const MAIL_INVITE_ILLUSTRATION: SesInlineImage | null = inlineImage('invite-illustration', 'invite-illustration.png', '');

/** Same envelope illustration as MAIL_INVITE_ILLUSTRATION, but with a gold admin star baked in — used when inviting someone as an org admin. */
export const MAIL_INVITE_ILLUSTRATION_ADMIN: SesInlineImage | null = inlineImage('invite-illustration-admin', 'invite-illustration-admin.png', '');
